// ZB prekės: mokesčių statusas + amžiaus apribojimo nuėmimas
// Paleisti: ?zb_tax_age_fix=1
add_action('init', function() {
    if ( ! isset($_GET['zb_tax_age_fix']) || ! current_user_can('manage_options') ) return;

    global $wpdb;

    $ids = $wpdb->get_col("
        SELECT p.ID 
        FROM {$wpdb->posts} p
        INNER JOIN {$wpdb->postmeta} pm ON pm.post_id = p.ID 
            AND pm.meta_key = '_zb_enabled' 
            AND pm.meta_value = 'yes'
        WHERE p.post_type = 'product'
        AND p.post_status != 'trash'
    ");

    $count = 0;
    foreach ( $ids as $id ) {
        update_post_meta($id, '_tax_status', 'taxable');
        update_post_meta($id, 'minimum_allowed_age', '');
        $count++;
    }

    echo '<pre>';
    echo "✅ Pataisyta: $count prekių\n";
    echo "   → Mokesčių statusas: Apmokestinama\n";
    echo "   → Amžiaus apribojimas: nuimtas\n";
    echo '</pre>';
    exit;
});
